import json, glob
from collections import defaultdict
groups = defaultdict(list)
allf = {}
for fp in sorted(glob.glob('findings/*.json')):
    data = json.load(open(fp))
    for f in data:
        key = (f['file'], f['line'], f['cwe'])
        groups[key].append((fp, f['id'], f['confidence']))
        allf[f['id']] = fp
dups = {k:v for k,v in groups.items() if len(v) > 1}
for k,v in dups.items():
    print(k, v)
print('total findings:', sum(len(json.load(open(fp))) for fp in glob.glob('findings/*.json')))
"
"}

